INSERT IGNORE INTO `aqi` VALUES (1,'一级','优','#02E300','空气质量令人满意，基本无空气污染。','各类人群可正常活动。',0,50,0,5,0,35,'空气清洁等级'),(2,'二级','良','#FFFF00','空气质量可以接受，但某些污染物可能对极少数异常敏感人群健康有较弱影响。','极少数异常敏感人群应减少户外活动。',51,150,6,10,36,75,'总体属于良好范围'),(3,'三级','轻度污染','#FF7E00','易感人群症状有轻度加剧，健康人群出现刺激症状。','儿童、老年人及心脏病、呼吸系统疾病患者应减少长时间、高强度的户外锻炼。',151,475,11,35,76,115,'从本级开始计为污染'),(4,'四级','中度污染','#FE0000','进一步加剧易感人群症状，可能对健康人群心脏、呼吸系统有影响。','儿童、老年人及心脏病、呼吸系统疾病患者避免长时间、高强度的户外锻炼，一般人群适量减少户外运动。',476,800,36,60,116,150,'需要重点关注'),(5,'五级','重度污染','#98004B','心脏病和肺病患者症状显著加剧，运动耐受力降低，健康人群普遍出现症状。','儿童、老年人和心脏病、肺病患者应停留在室内并停止户外运动，一般人群减少户外运动。',801,1600,61,90,151,250,'建议发布健康提示'),(6,'六级','严重污染','#7E0123','健康人群运动耐受力降低，有明显强烈症状，提前出现某些疾病。','儿童、老年人和病人应当留在室内，避免体力消耗，一般人群应避免户外活动。',1601,NULL,91,150,251,500,'最高污染等级');

